const iconPaths={home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3z"/>',dumbbell:'<path d="M6 7v10M3 9v6m15-8v10m3-8v6M6 12h12"/>',chart:'<path d="M4 20V10m6 10V4m6 16v-7m4 7H2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2m-2-8-2 2M6 18l-2 2M4 4l2 2m12 12 2 2"/>'};
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[el.dataset.icon]||iconPaths.chart}</svg>`);
let editorPlan=null;
function exerciseRow(e={name:'',sets:3,minReps:8,maxReps:12}){return `<fieldset class="exercise-editor"><legend>Übung</legend><label class="field">Name<input data-key="name" value="${esc(e.name)}" placeholder="z. B. Bankdrücken" required maxlength="100"></label><div class="rep-fields">${[['sets','Sätze',1,12],['minReps','Von',1,100],['maxReps','Bis',1,100]].map(([key,label,min,max])=>`<label class="field">${label}<input data-key="${key}" type="number" min="${min}" max="${max}" value="${e[key]}" required></label>`).join('')}</div><button class="remove-exercise" type="button">Übung entfernen</button></fieldset>`}
newPlan=function(p=null){editorPlan=p;const d=dialog(`<p class="eyebrow">${p?'DEIN PLAN WÄCHST MIT DIR':'DEIN NÄCHSTES KAPITEL'}</p><h2>${p?'Plan bearbeiten':'Neuer Trainingsplan'}</h2><form id="plan-form"><label class="field">Planname<input name="name" value="${esc(p?.name||'')}" maxlength="100" placeholder="z. B. Oberkörper A" required></label><div id="exercise-list">${(p?.exercises||[{}]).map(e=>exerciseRow(e.name?e:undefined)).join('')}</div><button type="button" class="finish-button" id="add-exercise">+ Übung hinzufügen</button><p class="sub">Sätze und Wiederholungsbereich festlegen. Dein Trainer in ChatGPT hilft dir bei der Auswahl.</p><button class="complete-set" type="submit">${p?'Neue Version speichern':'Trainingsplan speichern'}</button><p role="alert" id="plan-error"></p></form>`);const removers=()=>d.querySelectorAll('.remove-exercise').forEach(b=>b.onclick=()=>{if(d.querySelectorAll('.exercise-editor').length>1)b.closest('fieldset').remove()});removers();d.querySelector('#add-exercise').onclick=()=>{d.querySelector('#exercise-list').insertAdjacentHTML('beforeend',exerciseRow());removers()};d.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const exercises=[...d.querySelectorAll('.exercise-editor')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-key]')].map(input=>[input.dataset.key,input.dataset.key==='name'?input.value.trim():Number(input.value)])));const args={name:new FormData(ev.target).get('name'),exercises,...(p?{planId:p.id}:{})};const r=await save(p?'update_training_plan':'create_training_plan',args);if(r){d.close();toast('Trainingsplan gespeichert')}else d.querySelector('#plan-error').textContent='Bitte Namen und Wiederholungsbereiche prüfen.'}}
const baseRender=render;render=function(){baseRender();document.querySelectorAll('#dashboard [data-act="plan"]').forEach(b=>{const edit=document.createElement('button');edit.className='text-button';edit.textContent='Plan bearbeiten';edit.onclick=()=>newPlan(state.plans.find(p=>p.id===b.dataset.id));b.after(edit)});if(screen==='progress')renderCharts();if(screen==='workout')addSteppers();};
function addSteppers(){document.querySelectorAll('#set-form input[type=number]').forEach(input=>{const row=document.createElement('div');row.className='quick-adjust';for(const delta of [-1,1]){const b=document.createElement('button');b.type='button';b.textContent=delta===1?'+':'−';b.setAttribute('aria-label',(delta===1?'Erhöhen: ':'Reduzieren: ')+(input.name==='weight'?'Gewicht':'Wiederholungen'));b.onclick=()=>{const step=input.name==='weight'?2.5:1;input.value=Math.min(Number(input.max),Math.max(Number(input.min),Number(input.value)+step*delta))};row.appendChild(b)}input.after(row)})}
function renderCharts(){const host=document.querySelector('#progress');const names=[...new Set(state.sessions.flatMap(s=>s.exercises.map(e=>e.name)))];if(!names.length)return;const panel=document.createElement('article');panel.className='chart-card';panel.style.marginBottom='24px';panel.innerHTML='<div class="section-head"><div><p class="eyebrow">KRAFTENTWICKLUNG</p><h3>Deine Leistung über Zeit</h3></div></div><label class="field">Übung<select id="chart-exercise">'+names.map(n=>`<option>${esc(n)}</option>`).join('')+'</select></label><div id="strength-chart"></div>';host.querySelector('.topbar').after(panel);const draw=()=>{const name=panel.querySelector('select').value;const points=state.sessions.filter(s=>s.status==='completed').map(s=>{const sets=s.sets.filter(x=>x.unit==='kg'&&s.exercises.find(e=>e.id===x.exerciseId)?.name===name&&x.reps<=12);return sets.length?{date:new Date(s.startedAt).toLocaleDateString('de-DE'),value:Math.max(...sets.map(x=>x.weight*(1+x.reps/30)))}:null}).filter(Boolean);const out=panel.querySelector('#strength-chart');if(points.length<2){out.innerHTML='<p class="sub">Nach zwei abgeschlossenen Einheiten mit dieser Übung siehst du hier die Entwicklung deines geschätzten 1RM. Keine erfundenen Kurven.</p>';return}const max=Math.max(...points.map(p=>p.value))*1.05,min=Math.min(...points.map(p=>p.value))*.9;const coords=points.map((p,i)=>[20+i*660/(points.length-1),190-(p.value-min)/(max-min||1)*160]);out.innerHTML=`<svg role="img" aria-label="Entwicklung des geschätzten 1RM für ${esc(name)}" viewBox="0 0 700 220" style="width:100%;max-height:280px"><path d="${coords.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' ')}" fill="none" stroke="var(--accent)" stroke-width="3"/>${coords.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="var(--accent)"><title>${points[i].date}: ${points[i].value.toFixed(1)} kg geschätztes 1RM</title></circle>`).join('')}</svg><details><summary>Messpunkte anzeigen</summary>${points.map(p=>`<p>${p.date}: ${p.value.toFixed(1)} kg</p>`).join('')}</details><p class="sub">Schätzwert aus Gewicht und Wiederholungen (Epley), kg-Sätze bis 12 Wdh.</p>`};panel.querySelector('select').onchange=draw;draw();}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&!busy&&!document.querySelector('dialog[open]'))refresh()});
setInterval(()=>{if(!busy&&screen!=='workout'&&!document.querySelector('dialog[open]')&&document.visibilityState==='visible')refresh()},15000);
setInterval(async()=>{if(busy||screen!=='workout'||document.visibilityState!=='visible'||document.querySelector('#set-form:focus-within'))return;await refresh()},5000);
const polishedRender=render;render=function(){polishedRender();const bar=document.querySelector('.view.active .topbar');if(bar){const theme=document.createElement('button');theme.className='icon-button';theme.setAttribute('aria-label','Dark Mode oder Light Mode wechseln');theme.innerHTML='<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true">'+iconPaths.sun+'</svg>';theme.onclick=()=>{const root=document.documentElement;root.dataset.theme=root.dataset.theme==='light'?'dark':'light';localStorage.setItem('gym-theme',root.dataset.theme)};bar.appendChild(theme)}if(screen==='progress'){const b=document.createElement('button');b.className='finish-button';b.textContent='Meine Daten exportieren';b.onclick=async()=>{const data=await save('export_training_data',{});if(!data)return;const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='gym-mastery-export.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};document.querySelector('#progress').append(b)}if(embedded){const card=document.createElement('article');card.className='coach-card';card.style.marginTop='24px';card.innerHTML='<p class="eyebrow">DEIN COACH IST DABEI</p><h3>Was möchtest du wissen?</h3><form id="coach-question"><label class="field">Deine Frage<input name="question" placeholder="Welche Übung kann ich stattdessen machen?" required maxlength="1000"></label><button class="complete-set">Coach fragen →</button></form>';document.querySelector('.view.active').append(card);card.querySelector('form').onsubmit=async ev=>{ev.preventDefault();try{await rpc('ui/message',{role:'user',content:[{type:'text',text:new FormData(ev.target).get('question')}]});toast('Frage an deinen Coach übergeben')}catch(e){toast(e.message)}}}};
document.documentElement.dataset.theme=localStorage.getItem('gym-theme')||'dark';
const accessibleRender=render;render=function(){accessibleRender();document.querySelectorAll('.nav-item').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===screen)))};
